+        Expression otherExpression = leftResolution.unresolved() ? left() : right();
+        TypeResolutions.ParamOrdinal otherParamOrdinal = leftResolution.unresolved() ? FIRST : SECOND;
+        spatialDataType = spatialExpression.dataType();
