+        DataType[] cartesianDataTypes = { KEYWORD, EsqlDataTypes.CARTESIAN_POINT, EsqlDataTypes.CARTESIAN_SHAPE };
+        addSpatialCombinations(suppliers, cartesianDataTypes);
