+    private static DataType pickSpatialType(DataType leftType, DataType rightType) {
+        if (isSpatial(leftType)) {
+            return leftType;
+        } else if (isSpatial(rightType)) {
+            return rightType;
+        } else {
+            return EsqlDataTypes.CARTESIAN_SHAPE;
+        }
+    }
+
+    private static String pickSpatialPrefix(DataType leftType, DataType rightType) {
+        return isSpatialGeo(pickSpatialType(leftType, rightType)) ? "Geo" : "Cartesian";
